-- LK MUSIC PLAYER: arquivos .ogg locais em LK_DOORS_MUSIC
-- ============================================================
local LKMusicFolder = "LK_DOORS_MUSIC"
local LKMusicFiles = {}
local LKMusicSelected = nil
local LKMusicSound = nil
local LKMusicVolume = 5
local LKMusicStatus = nil
local LKMusicListFrame = nil
local LKMusicVolumeLabel = nil
local LKMusicSelectedLabel = nil

pcall(function() LKMakeFolder(LKMusicFolder) end)

local function LKMusicSetStatus(message, color)
    if LKMusicStatus and LKMusicStatus.Parent then
        LKMusicStatus.Text = tostring(message or "")
        LKMusicStatus.TextColor3 = color or Color3.fromRGB(180,190,210)
    end
end

local function LKMusicStop()
    if LKMusicSound then
        pcall(function() LKMusicSound:Stop() end)
        pcall(function() LKMusicSound:Destroy() end)
        LKMusicSound = nil
    end
end

local function LKMusicMakeButton(parent, text, width, callback, color)
    local b = Instance.new("TextButton")
    b.Size = UDim2.new(width or 1, width and 0 or -2, 0, 40)
    b.BackgroundColor3 = color or Color3.fromRGB(48,43,72)
    b.Text = text
    b.TextColor3 = White
    b.Font = Enum.Font.GothamBold
    b.TextSize = 11
    b.AutoButtonColor = true
    b.Parent = parent
    Instance.new("UICorner",b).CornerRadius = UDim.new(0,9)
    b.Activated:Connect(function()
        if callback then
            local ok,err = pcall(callback)
            if not ok then
                warn("[LK MUSIC]",err)
                LKMusicSetStatus("Erro: "..tostring(err), Color3.fromRGB(255,110,110))
            end
        end
    end)
    return b
end

local function LKMusicRefresh()
    LKMusicFiles = {}
    if type(listfiles) ~= "function" then
        LKMusicSetStatus("Seu executor não oferece listfiles().", Color3.fromRGB(255,125,125))
        return
    end

    local folders = {LKMusicFolder, "Delta/"..LKMusicFolder,
        "/storage/emulated/0/Delta/"..LKMusicFolder}
    local seen = {}
    for _,folder in ipairs(folders) do
        local ok, files = pcall(listfiles, folder)
        if ok and type(files) == "table" then
            for _,filePath in ipairs(files) do
                if type(filePath) == "string" and filePath:lower():match("%.ogg$") then
                    local normalized = filePath:gsub("\\","/")
                    if not seen[normalized] then
                        seen[normalized] = true
                        LKMusicFiles[#LKMusicFiles+1] = {
                            path = filePath,
                            name = normalized:match("([^/]+)$") or normalized
                        }
                    end
                end
            end
        end
    end
    table.sort(LKMusicFiles,function(a,b) return a.name:lower() < b.name:lower() end)

    if LKMusicListFrame then
        for _,child in ipairs(LKMusicListFrame:GetChildren()) do
            if child:IsA("TextButton") or child.Name == "EmptyMessage" then child:Destroy() end
        end
        local layout = LKMusicListFrame:FindFirstChildOfClass("UIListLayout")
        local y = 0
        for index,entry in ipairs(LKMusicFiles) do
            local row = Instance.new("TextButton")
            row.Name = "MusicTrack_"..index
            row.Size = UDim2.new(1,-4,0,38)
            row.BackgroundColor3 = (LKMusicSelected == entry.path) and Color3.fromRGB(70,48,108) or Color3.fromRGB(29,32,49)
            row.Text = "  "..entry.name
            row.TextColor3 = White
            row.Font = Enum.Font.GothamSemibold
            row.TextSize = 10
            row.TextXAlignment = Enum.TextXAlignment.Left
            row.TextTruncate = Enum.TextTruncate.AtEnd
            row.Parent = LKMusicListFrame
            Instance.new("UICorner",row).CornerRadius = UDim.new(0,8)
            row.Activated:Connect(function()
                LKMusicSelected = entry.path
                if LKMusicSelectedLabel then LKMusicSelectedLabel.Text = "Selecionada: "..entry.name end
                LKMusicRefresh()
            end)
        end
        if #LKMusicFiles == 0 then
            local empty = Instance.new("TextLabel")
            empty.Name = "EmptyMessage"
            empty.Size = UDim2.new(1,-4,0,40)
            empty.BackgroundTransparency = 1
            empty.Text = "Nenhum arquivo .ogg encontrado na pasta."
            empty.TextColor3 = Muted
            empty.Font = Enum.Font.Gotham
            empty.TextSize = 10
            empty.TextWrapped = true
            empty.Parent = LKMusicListFrame
        end
        if layout then
            task.defer(function()
                if LKMusicListFrame and LKMusicListFrame.Parent then
                    LKMusicListFrame.CanvasSize = UDim2.fromOffset(0,layout.AbsoluteContentSize.Y+6)
                end
            end)
        end
    end

    LKMusicSetStatus(#LKMusicFiles.." arquivo(s) .ogg encontrado(s).")
end

local LKMusicPage = Pages.MUSICA
if LKMusicPage then
    local heading = Instance.new("TextLabel")
    heading.Size = UDim2.new(1,-4,0,30)
    heading.BackgroundTransparency = 1
    heading.Text = "PLAYER DE MÚSICA LOCAL"
    heading.TextColor3 = Accent2
    heading.Font = Enum.Font.GothamBlack
    heading.TextSize = 13
    heading.Parent = LKMusicPage

    local info = Instance.new("TextLabel")
    info.Size = UDim2.new(1,-4,0,32)
    info.BackgroundTransparency = 1
    info.Text = "Coloque seus arquivos .ogg dentro da pasta LK_DOORS_MUSIC"
    info.TextColor3 = Muted
    info.Font = Enum.Font.Gotham
    info.TextSize = 9
    info.TextWrapped = true
    info.Parent = LKMusicPage

    LKMusicSelectedLabel = Instance.new("TextLabel")
    LKMusicSelectedLabel.Size = UDim2.new(1,-4,0,25)
    LKMusicSelectedLabel.BackgroundTransparency = 1
    LKMusicSelectedLabel.Text = "Nenhuma música selecionada"
    LKMusicSelectedLabel.TextColor3 = White
    LKMusicSelectedLabel.Font = Enum.Font.GothamSemibold
    LKMusicSelectedLabel.TextSize = 10
    LKMusicSelectedLabel.TextXAlignment = Enum.TextXAlignment.Left
    LKMusicSelectedLabel.TextTruncate = Enum.TextTruncate.AtEnd
    LKMusicSelectedLabel.Parent = LKMusicPage

    local controls = Instance.new("Frame")
    controls.Size = UDim2.new(1,-4,0,42)
    controls.BackgroundTransparency = 1
    controls.Parent = LKMusicPage
    local controlsLayout = Instance.new("UIListLayout")
    controlsLayout.FillDirection = Enum.FillDirection.Horizontal
    controlsLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    controlsLayout.Padding = UDim.new(0,6)
    controlsLayout.Parent = controls

    local play = LKMusicMakeButton(controls,"▶ TOCAR",0.34,function()
        if not LKMusicSelected then LKMusicSetStatus("Selecione uma música primeiro.",Color3.fromRGB(255,190,100)); return end
        local assetFn = type(getcustomasset)=="function" and getcustomasset or (type(getsynasset)=="function" and getsynasset)
        if not assetFn then LKMusicSetStatus("Executor sem getcustomasset/getsynasset.",Color3.fromRGB(255,110,110)); return end
        LKMusicStop()
        local asset
        local paths = {LKMusicSelected,"Delta/"..LKMusicSelected,"/storage/emulated/0/Delta/"..LKMusicSelected}
        for _,assetPath in ipairs(paths) do
            local ok,result = pcall(assetFn,assetPath)
            if ok and type(result)=="string" and result~="" then asset=result; break end
        end
        if not asset then LKMusicSetStatus("Não foi possível carregar esse .ogg.",Color3.fromRGB(255,110,110)); return end
        local sound = Instance.new("Sound")
        sound.Name = "LK_DOORS_LOCAL_MUSIC"
        sound.SoundId = asset
        sound.Volume = LKMusicVolume
        sound.Looped = false
        sound.Parent = SoundService
        LKMusicSound = sound
        LKMusicSetStatus("Carregando áudio...")
        task.spawn(function()
            local started = os.clock()
            while sound.Parent and not sound.IsLoaded and os.clock()-started < 10 do task.wait(0.15) end
            if not sound.Parent or LKMusicSound ~= sound then return end
            if not sound.IsLoaded then
                LKMusicStop()
                LKMusicSetStatus("Falha ao carregar o áudio. Confira se o .ogg é válido.",Color3.fromRGB(255,110,110))
                return
            end
            local ok,err = pcall(function() sound:Play() end)
            if ok then LKMusicSetStatus("Reproduzindo: "..(LKMusicSelectedLabel.Text:gsub("^Selecionada: ","")),Accent2)
            else LKMusicSetStatus("Erro ao reproduzir: "..tostring(err),Color3.fromRGB(255,110,110)); LKMusicStop() end
        end)
        sound.Ended:Connect(function()
            if LKMusicSound == sound then LKMusicSound = nil end
            pcall(function() sound:Destroy() end)
            LKMusicSetStatus("Reprodução finalizada.")
        end)
    end,Color3.fromRGB(49,103,83))
    play.Size = UDim2.new(0.34,-4,0,40)

    local pause = LKMusicMakeButton(controls,"Ⅱ PAUSAR",0.33,function()
        if not LKMusicSound then LKMusicSetStatus("Nenhuma música está carregada."); return end
        if LKMusicSound.IsPlaying then LKMusicSound:Pause(); LKMusicSetStatus("Música pausada.")
        else LKMusicSound:Resume(); LKMusicSetStatus("Reproduzindo novamente.",Accent2) end
    end)
    pause.Size = UDim2.new(0.33,-4,0,40)

    local stop = LKMusicMakeButton(controls,"■ PARAR",0.33,function()
        LKMusicStop()
        LKMusicSetStatus("Reprodução parada.")
    end,Color3.fromRGB(105,53,65))
    stop.Size = UDim2.new(0.33,-4,0,40)

    local volumeRow = Instance.new("Frame")
    volumeRow.Size = UDim2.new(1,-4,0,38)
    volumeRow.BackgroundTransparency = 1
    volumeRow.Parent = LKMusicPage
    local volumeLayout = Instance.new("UIListLayout")
    volumeLayout.FillDirection = Enum.FillDirection.Horizontal
    volumeLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
    volumeLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    volumeLayout.Padding = UDim.new(0,7)
    volumeLayout.Parent = volumeRow
    local volDown = LKMusicMakeButton(volumeRow,"−",0.18,function()
        LKMusicVolume = math.max(0,math.floor((LKMusicVolume-0.5)*10+0.5)/10)
        if LKMusicSound then LKMusicSound.Volume = LKMusicVolume end
        if LKMusicVolumeLabel then LKMusicVolumeLabel.Text = "Volume: "..string.format("%.1f",LKMusicVolume).." / 10" end
    end)
    volDown.Size = UDim2.new(0,38,0,32)
    LKMusicVolumeLabel = Instance.new("TextLabel")
    LKMusicVolumeLabel.Size = UDim2.new(1,-100,0,32)
    LKMusicVolumeLabel.BackgroundTransparency = 1
    LKMusicVolumeLabel.Text = "Volume: 5.0 / 10"
    LKMusicVolumeLabel.TextColor3 = White
    LKMusicVolumeLabel.Font = Enum.Font.GothamBold
    LKMusicVolumeLabel.TextSize = 10
    LKMusicVolumeLabel.Parent = volumeRow
    local volUp = LKMusicMakeButton(volumeRow,"+",0.18,function()
        LKMusicVolume = math.min(10,math.floor((LKMusicVolume+0.5)*10+0.5)/10)
        if LKMusicSound then LKMusicSound.Volume = LKMusicVolume end
        if LKMusicVolumeLabel then LKMusicVolumeLabel.Text = "Volume: "..string.format("%.1f",LKMusicVolume).." / 10" end
    end)
    volUp.Size = UDim2.new(0,38,0,32)

    LKMusicMakeButton(LKMusicPage,"↻ ATUALIZAR LISTA",1,function() LKMusicRefresh() end)

    LKMusicStatus = Instance.new("TextLabel")
    LKMusicStatus.Size = UDim2.new(1,-4,0,30)
    LKMusicStatus.BackgroundTransparency = 1
    LKMusicStatus.Text = "Preparando lista..."
    LKMusicStatus.TextColor3 = Muted
    LKMusicStatus.Font = Enum.Font.Gotham
    LKMusicStatus.TextSize = 9
    LKMusicStatus.TextWrapped = true
    LKMusicStatus.Parent = LKMusicPage

    local listTitle = Instance.new("TextLabel")
    listTitle.Size = UDim2.new(1,-4,0,22)
    listTitle.BackgroundTransparency = 1
    listTitle.Text = "SUAS MÚSICAS"
    listTitle.TextColor3 = Accent2
    listTitle.Font = Enum.Font.GothamBlack
    listTitle.TextSize = 10
    listTitle.TextXAlignment = Enum.TextXAlignment.Left
    listTitle.Parent = LKMusicPage

    LKMusicListFrame = Instance.new("ScrollingFrame")
    LKMusicListFrame.Name = "LocalMusicList"
    LKMusicListFrame.Size = UDim2.new(1,-4,0,210)
    LKMusicListFrame.BackgroundColor3 = Color3.fromRGB(20,22,35)
    LKMusicListFrame.BorderSizePixel = 0
    LKMusicListFrame.ScrollBarThickness = 3
    LKMusicListFrame.ScrollBarImageColor3 = Accent2
    LKMusicListFrame.CanvasSize = UDim2.new(0,0,0,0)
    LKMusicListFrame.Parent = LKMusicPage
    Instance.new("UICorner",LKMusicListFrame).CornerRadius = UDim.new(0,9)
    local musicListLayout = Instance.new("UIListLayout")
    musicListLayout.Padding = UDim.new(0,5)
    musicListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    musicListLayout.Parent = LKMusicListFrame
    musicListLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        if LKMusicListFrame then LKMusicListFrame.CanvasSize = UDim2.fromOffset(0,musicListLayout.AbsoluteContentSize.Y+8) end
    end)
    LKMusicRefresh()
    CleanupHooks[#CleanupHooks + 1] = LKMusicStop
end

NotificationCount = 0
ActiveNotifications = {}

function LK_LayoutNotifications()
    local y = 62
    for index,entry in ipairs(ActiveNotifications) do
        local notice = entry.Frame
        if notice and notice.Parent then
            TweenService:Create(
                notice,
                TweenInfo.new(0.22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
                {Position = UDim2.new(1,-14,0,y)}
            ):Play()
            y = y + entry.Height + 8
        end
    end
end

function Notify(message, alertColor, alertTitle, advice)
    PlayMenuSound("notification")
    NotificationCount = NotificationCount + 1

    local hasAdvice = type(advice) == "string" and advice ~= ""
    local cardHeight = hasAdvice and 82 or 55
    local notice = Instance.new("Frame")
    notice.Name = "LKNotification_"..NotificationCount
    notice.Size = UDim2.fromOffset(286,0)
    notice.AnchorPoint = Vector2.new(1,0)
    notice.Position = UDim2.new(1,300,0,62)
    notice.BackgroundColor3 = Panel
    notice.BorderSizePixel = 0
    notice.ClipsDescendants = true
    notice.Parent = Gui

    table.insert(ActiveNotifications,{Frame=notice,Height=cardHeight})
    LK_LayoutNotifications()

    Instance.new("UICorner",notice).CornerRadius = UDim.new(0,10)

    local chosenColor = alertColor or Purple
    local stroke = Instance.new("UIStroke")
    stroke.Color = chosenColor
    stroke.Thickness = 1.8
    stroke.Parent = notice

    local triangle = Instance.new("TextLabel")
    triangle.Position = UDim2.fromOffset(7,15)
    triangle.Size = UDim2.fromOffset(28,34)
    triangle.BackgroundTransparency = 1
    local isBlack = chosenColor.R < 0.18 and chosenColor.G < 0.18 and chosenColor.B < 0.18
    local isRed = chosenColor.R > chosenColor.G * 1.35 and chosenColor.R > chosenColor.B * 1.2
    triangle.Text = "▲"
    triangle.TextColor3 = chosenColor
    triangle.TextSize = 25
    triangle.Font = Enum.Font.GothamBlack
    triangle.Parent = notice

    local left = 39
    local title = Instance.new("TextLabel")
    title.Position = UDim2.fromOffset(left,5)
    title.Size = UDim2.new(1,-left-9,0,17)
    title.BackgroundTransparency = 1
    title.Text = alertTitle or "LK DOORS SYSTEM"
    title.TextColor3 = chosenColor
    title.TextSize = 11
    title.Font = Enum.Font.GothamBlack
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = notice

    local messageLabel = Instance.new("TextLabel")
    messageLabel.Position = UDim2.fromOffset(left,24)
    messageLabel.Size = UDim2.new(1,-left-9,0,hasAdvice and 20 or 23)
    messageLabel.BackgroundTransparency = 1
    messageLabel.Text = tostring(message)
    messageLabel.TextColor3 = White
    messageLabel.TextSize = 12
    messageLabel.Font = Enum.Font.GothamBold
    messageLabel.TextXAlignment = Enum.TextXAlignment.Left
    messageLabel.TextTruncate = Enum.TextTruncate.AtEnd
    messageLabel.Parent = notice

    if hasAdvice then
        local adviceLabel = Instance.new("TextLabel")
        adviceLabel.Position = UDim2.fromOffset(left,45)
        adviceLabel.Size = UDim2.new(1,-left-9,0,29)
        adviceLabel.BackgroundTransparency = 1
        adviceLabel.Text = "DICA: "..advice
        adviceLabel.TextColor3 = White
        adviceLabel.TextSize = 10
        adviceLabel.Font = Enum.Font.Gotham
        adviceLabel.TextXAlignment = Enum.TextXAlignment.Left
        adviceLabel.TextYAlignment = Enum.TextYAlignment.Top
        adviceLabel.TextWrapped = true
        adviceLabel.Parent = notice
    end

    local currentIndex = #ActiveNotifications
    local targetY = 62
    for i=1,currentIndex-1 do
        targetY = targetY + ActiveNotifications[i].Height + 8
    end

    TweenService:Create(
        notice,
        TweenInfo.new(0.35,Enum.EasingStyle.Back,Enum.EasingDirection.Out),
        {
            Size = UDim2.fromOffset(286,cardHeight),
            Position = UDim2.new(1,-14,0,targetY)
        }
    ):Play()

    task.delay(hasAdvice and 5.5 or 3.2,function()
        if not notice.Parent then return end

        local exitTween = TweenService:Create(
            notice,
            TweenInfo.new(0.3,Enum.EasingStyle.Quad,Enum.EasingDirection.In),
            {
                Position = UDim2.new(1,300,0,notice.Position.Y.Offset),
                BackgroundTransparency = 1
            }
        )
        for _,child in ipairs(notice:GetChildren()) do
            if child:IsA("TextLabel") then
                TweenService:Create(child,TweenInfo.new(0.25),{TextTransparency=1}):Play()
            elseif child:IsA("UIStroke") then
                TweenService:Create(child,TweenInfo.new(0.25),{Transparency=1}):Play()
            end
        end
        exitTween:Play()
        exitTween.Completed:Wait()
        notice:Destroy()

        for i=#ActiveNotifications,1,-1 do
            if ActiveNotifications[i].Frame == notice then
                table.remove(ActiveNotifications,i)
                break
            end
        end
        LK_LayoutNotifications()
    end)
end

function Norm(text)
    return (tostring(text):lower():gsub("[%s_%-%.]",""))
end

function HasAny(text,words)
    for _,word in ipairs(words) do
        if text:find(word,1,true) then
            return true
        end
    end

    return false
end

ESPObjects = {}

EntityNames = {
    "rush","ambush","figure","seek","screech",
    "a60","a120","blitz","lookman","halt",
    "dupe","dread","eyes","grumble","giggle"
}

ItemNames = {
    "goldgun", "lighter", "flashlight", "crucifix",
    "vitamin", "vitamins", "lockpick", "lockpicks", "shears",
    "bandage", "bandages", "candle", "smoothie", "shakelight",
    "straplight", "bulklight", "compass", "flashbang",
    "glowsticks", "tipjar", "nanner", "gweenpeel",
    "skeletonkey", "holywater"
}

function IsItem(name)
    local normalized = Norm(name)
    if normalized == "keyobtain" or normalized == "candlemedium" then
        return false
    end
    for _, item in ipairs(ItemNames) do
        if normalized == Norm(item) then
            return true
        end
    end
    return false
end

function GetPart(object)
    if object:IsA("BasePart") then return object end

    if object:IsA("Model") then
        return object.PrimaryPart
            or object:FindFirstChildWhichIsA("BasePart",true)
    end

    if object:IsA("Tool") then
        return object:FindFirstChildWhichIsA("BasePart",true)
    end
end

function IsEntity(name)
    local normalized = name:lower():gsub("[%s_%-]","")

    
    
    if normalized:find("painting",1,true)
    or normalized == "seekarm"
    or normalized:find("sideroom",1,true) then
        return false
    end

    for _,entity in ipairs(EntityNames) do
        if normalized:find(entity,1,true) then
            return true
        end
    end

    return false
end

function IsItem(name)
    local normalized = Norm(name)

    -- Exclude CandleStick shelves and candle holders, but keep the Lighter pickup.
    if normalized == "candlestick"
    or normalized == "candleholder"
    or normalized == "candlestand"
    or normalized == "candlemedium"
    or normalized == "candle_medium" then
        return false
    end

    for _,item in ipairs(ItemNames) do
        if normalized == Norm(item) then
            return true
        end
    end

    return false
end

-- The Lighter ESP is valid only for the real pickup:
-- a Tool, or a MeshPart that has a ProximityPrompt (including inside its model).
function IsValidLighterPickup(object)
    if not object then return false end

    -- O item original pode ser uma Tool.
    if object:IsA("Tool") then
        return true
    end

    -- Aceita MeshPart ou Part com SpecialMesh, mas exige ProximityPrompt
    -- dentro do próprio objeto (não basta a prateleira ter um prompt).
    local isMeshObject = object:IsA("MeshPart")
    if object:IsA("BasePart") and not isMeshObject then
        for _,child in ipairs(object:GetChildren()) do
            if child:IsA("SpecialMesh") then
                isMeshObject = true
                break
            end
        end
    end

    if not isMeshObject then
        return false
    end

    for _,desc in ipairs(object:GetDescendants()) do
        if desc:IsA("ProximityPrompt") then
            return true
        end
    end

    return false
end

function IsItemForESP(object)
    if not object or not IsItem(object.Name) then return false end
    if Norm(object.Name) == "lighter" then
        return IsValidLighterPickup(object)
    end
    return true
end

local function IsBookshelfModel(model)
    if not model or not model:IsA("Model") then return false end

    local bookCount = 0
    for _,desc in ipairs(model:GetDescendants()) do
        local n = Norm(desc.Name)
        if n:find("book",1,true) then
            bookCount = bookCount + 1
            if bookCount >= 2 then
                return true
            end
        end
    end

    return false
end

local function IsExcludedShelf(object)
    if not object then return false end

    local current = object
    while current and current ~= Workspace do
        local n = Norm(current.Name)

        -- CandleStick is always a shelf/decoration exclusion.
        if n == "candlestick" then
            return true
        end

        current = current.Parent
    end

    return false
end

function AddESP(object,category,color,label)
    if not object or not object.Parent or ESPObjects[object]
    or IsExcludedShelf(object) then
        return
    end

    local highlight = Instance.new("Highlight")
    highlight.Name = "LK_ESP"
    highlight.Adornee = object
    highlight.FillColor = color
    highlight.OutlineColor = color
    highlight.FillTransparency = 0.78
    highlight.OutlineTransparency = 0
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Parent = Gui

    local part = GetPart(object)
    local billboard

    if part then
        billboard = Instance.new("BillboardGui")
        billboard.Name = "LK_ESP_LABEL"
        billboard.Adornee = part
        billboard.Size = UDim2.fromOffset(150,28)
        billboard.StudsOffset = Vector3.new(0,3,0)
        billboard.AlwaysOnTop = true
        billboard.Parent = Gui

        local text = Instance.new("TextLabel")
        text.Size = UDim2.fromScale(1,1)
        text.BackgroundTransparency = 1
        text.Text = label
        text.TextColor3 = color
        text.TextStrokeTransparency = 0
        text.TextSize = 12
        text.Font = Enum.Font.GothamBold
        text.Parent = billboard
    end

    ESPObjects[object] = {
        Category = category,
        Highlight = highlight,
        Billboard = billboard
    }
end

function RemoveCategory(category)
    for object,data in pairs(ESPObjects) do
        if data.Category == category then
            if data.Highlight then data.Highlight:Destroy() end
            if data.Billboard then data.Billboard:Destroy() end
            ESPObjects[object] = nil
        end
    end
end

function ClearESPObjects()
    for object,data in pairs(ESPObjects) do
        if data.Highlight then data.Highlight:Destroy() end
        if data.Billboard then data.Billboard:Destroy() end
    end

    table.clear(ESPObjects)
end

CleanupHooks[#CleanupHooks + 1] = ClearESPObjects

Buckets = {
    entity = {},
    book = {},
    lever = {},
    door = {},
    item = {},
    chest = {},
    battery = {}
}

BatteryNameExclude = {
    "charger","station","socket","slot","icon",
    "indicator","meter","gauge"
}

function IsBatteryName(name)
    local n = Norm(name)

    
    if n:find("^livebreakerpolepickup") then return true end

    if not (n:find("^battery") or n:find("^batteries")) then
        return false
    end

    return not HasAny(n,BatteryNameExclude)
end

function IndexObject(object)
    if IsExcludedShelf(object) then return end
    local name = object.Name
    local className = object.ClassName

    if className == "Model" or className == "Tool" then
        if className == "Model" and IsEntity(name) then
            Buckets.entity[object] = true
        end
        local lowerName = string.lower(name)
        if className == "Model" and (lowerName == "door" or lowerName:match("^door%d+$")) then
            Buckets.door[object] = true
        end
        local chestName = string.lower(name)
        if className == "Model" and (chestName:find("chest",1,true) or chestName:find("treasurechest",1,true)) then
            Buckets.chest[object] = true
        end

        if name == "LiveHintBook" then
            Buckets.book[object] = true
        elseif name == "LeverForGate" then
            Buckets.lever[object] = true
        end

        if IsItemForESP(object) then
            Buckets.item[object] = true
        end

        if IsBatteryName(name) then
            Buckets.battery[object] = true
        end

        return
    end

    
    
    local first = name:byte(1)

    if first == 68 or first == 76 or first == 66 or first == 98 then
        if not object:IsA("BasePart") then return end

        if string.lower(name) == "door" or string.lower(name):match("^door%d+$") then
            Buckets.door[object] = true
        elseif name == "LiveHintBook" then
            Buckets.book[object] = true
        elseif name == "LeverForGate" then
            Buckets.lever[object] = true
        elseif IsBatteryName(name) then
            Buckets.battery[object] = true
        end
    end
end

SeenEntities = {}

function EntitySpawned(object)
    if not object or not object:IsA("Model") then return end
    if not object.Parent or not IsEntity(object.Name) then return end
    if SeenEntities[object] then return end

    SeenEntities[object] = true

    if Settings.Notifier then
        local entity = Norm(object.Name)
        local color = Color3.fromRGB(255,205,55)
        local title = "⚠ ALERTA DE ENTIDADE"
        local advice = "Fique atento e observe o ambiente."

        if entity:find("rush",1,true) then
            color = Color3.fromRGB(255,205,55)
            advice = "Entre em um armário ou esconderijo e espere ele passar."
        elseif entity:find("ambush",1,true) then
            color = Color3.fromRGB(255,65,65)
            advice = "Entre no esconderijo; saia quando passar e volte quando retornar. Repita."
        elseif entity:find("figure",1,true) then
            color = Color3.fromRGB(255,65,65)
            advice = "Agache, afaste-se e evite fazer barulho perto dele."
        elseif entity:find("seek",1,true) then
            color = Color3.fromRGB(255,65,65)
            advice = "Corra seguindo as indicações e desvie dos obstáculos."
        elseif entity:find("halt",1,true) then
            color = Color3.fromRGB(255,205,55)
            advice = "Quando aparecer VIRE-SE e ande na direção oposta."
        elseif entity:find("eyes",1,true) then
            color = Color3.fromRGB(255,205,55)
            advice = "Não olhe para os olhos; mantenha a câmera apontada para longe."
        elseif entity:find("screech",1,true) then
            color = Color3.fromRGB(255,205,55)
            advice = "Quando ouvir 'psst', procure o Screech e olhe diretamente para ele."
        elseif entity:find("dupe",1,true) then
            color = Color3.fromRGB(255,205,55)
            advice = "Confira o número da sala e os sons antes de abrir uma porta."
        elseif entity:find("giggle",1,true) then
            color = Color3.fromRGB(255,205,55)
            advice = "Olhe para cima e use a luz para afastá-lo, se disponível."
        elseif entity:find("grumble",1,true) then
            color = Color3.fromRGB(255,65,65)
            advice = "Afaste-se dos tentáculos e procure uma rota segura."
        elseif entity:find("dread",1,true)
        or entity:find("a60",1,true)
        or entity:find("a120",1,true)
        or entity:find("blitz",1,true)
        or entity:find("lookman",1,true) then
            color = Color3.fromRGB(20,20,20)
            advice = "PERIGO CRÍTICO: procure abrigo imediatamente; não há garantia de escape."
        end

        Notify("ENTIDADE: "..object.Name,color,title,advice)
    end
end

Track(Workspace.DescendantAdded:Connect(function(object)
    pcall(IndexObject,object)

    if not object:IsA("Model") then return end

    task.delay(0.15,function()
        if Running and object.Parent then
            EntitySpawned(object)
        end
    end)
end))

Track(Workspace.DescendantRemoving:Connect(function(object)
    local wasEntity = Buckets.entity[object]

    for _,bucket in pairs(Buckets) do
        bucket[object] = nil
    end

    if wasEntity then
        task.delay(1,function()
            if not object:IsDescendantOf(Workspace) then
                SeenEntities[object] = nil
            end
        end)
    end
end))

task.spawn(function()
    local processed = 0

    for _,object in ipairs(Workspace:GetDescendants()) do
        if not Running then return end

        pcall(IndexObject,object)

        if Buckets.entity[object] then
            SeenEntities[object] = true
        end

        processed = processed + 1
        if processed % 1500 == 0 then
            task.wait()
        end
    end
end)

function Scan()
    local desired = {}
    local currentRooms = Workspace:FindFirstChild("CurrentRooms")

    local function consider(object, category, color, label)
        if object and object.Parent and not desired[object] then
            desired[object] = {category, color, label}
        end
    end

    local function inspectObject(object)
        if not object or not object.Parent then return end
        if IsExcludedShelf(object) then return end
        local isModel = object:IsA("Model")
        local isTool = object:IsA("Tool")
        local isPart = object:IsA("BasePart")
        if not (isModel or isTool or isPart) then return end

        local name = object.Name
        local normalized = Norm(name)
        if object.Parent and object.Parent.Name == name then return end

        if (Settings.Entities or Settings.Notifier) and isModel and IsEntity(name) then
            EntitySpawned(object)
            if Settings.Entities then
                consider(object, "ENTITY", Color3.fromRGB(255,45,55), name)
            end
        end

        if Settings.Chest and isModel then
            if normalized == "chest" or normalized == "chestlock"
            or normalized == "chestbox" or normalized == "chestboxlocked"
            or normalized:find("treasurechest",1,true) then
                local locked = normalized:find("lock",1,true) ~= nil
                if not locked then
                    for _,desc in ipairs(object:GetDescendants()) do
                        local dn = Norm(desc.Name)
                        if dn:find("lock",1,true) or dn:find("padlock",1,true) then
                            locked = true
                            break
                        end
                    end
                end
                consider(object,
                    locked and "CHESTLOCK" or "CHEST",
                    locked and Color3.fromRGB(255,75,75) or Color3.fromRGB(255,190,55),
                    locked and "ChestLock" or "Chest")
            end
        end

        if Settings.Books and name == "LiveHintBook" then
            consider(object, "BOOK", Color3.fromRGB(40,255,110), "LIVRO")
        end

        if Settings.Lever and name == "LeverForGate" then
            consider(object, "LEVER", Color3.fromRGB(255,165,30), "ALAVANCA")
        end

        if Settings.Items and IsItemForESP(object) then
            -- Ignore nested duplicate parts when their containing model has the same name.
            local parent = object.Parent
            local duplicate = parent and parent.Name == name
            if not duplicate then
                consider(object, "ITEM", Color3.fromRGB(255,220,35), name)
            end
        end
    end

    if currentRooms then
        for _,room in ipairs(currentRooms:GetChildren()) do
            if Settings.Doors then
                local doorModel = room:FindFirstChild("Door")
                if doorModel and doorModel:IsA("Model")
                and doorModel:FindFirstChild("Door")
                and doorModel:FindFirstChild("Sign") then
                    local sign = doorModel:FindFirstChild("Sign")
                    local roomNumber
                    for _,desc in ipairs(sign:GetDescendants()) do
                        if desc:IsA("TextLabel") then
                            local digits = tostring(desc.Text):match("^%s*(%d+)%s*$")
                            if digits then
                                roomNumber = tonumber(digits)
                                break
                            end
                        end
                    end
                    if not roomNumber then
                        local roomIndex = tonumber(room.Name)
                        if roomIndex then roomNumber = roomIndex + 1 end
                    end
                    if roomNumber then
                        consider(doorModel, "DOOR", Color3.fromRGB(40,130,255),
                            "Door " .. tostring(roomNumber))
                    end
                end
            end

            for _,object in ipairs(room:GetDescendants()) do
                inspectObject(object)
            end
        end
    end

    -- Also scan dropped objects and entities that are not parented to CurrentRooms.
    local drops = Workspace:FindFirstChild("Drops")
    if drops then
        for _,object in ipairs(drops:GetDescendants()) do
            inspectObject(object)
        end
    end

    for _,object in ipairs(Workspace:GetChildren()) do
        if object:IsA("Model") and (Settings.Entities or Settings.Notifier) and IsEntity(object.Name) then
            EntitySpawned(object)
            if Settings.Entities then
                consider(object, "ENTITY", Color3.fromRGB(255,45,55), object.Name)
            end
        end
    end

    -- Notify once for newly encountered entities.
    for object,info in pairs(desired) do
        local old = ESPObjects[object]
        if not old or old.Category ~= info[1] then
            if old then
                SafeDestroy(old.Highlight)
                SafeDestroy(old.Billboard)
                ESPObjects[object] = nil
            end
            AddESP(object,info[1],info[2],info[3])
        end
    end

    local remove = {}
    for object,data in pairs(ESPObjects) do
        if IsExcludedShelf(object) or not object or not object.Parent or not desired[object] then
            table.insert(remove, object)
        end
    end
    for _,object in ipairs(remove) do
        local data = ESPObjects[object]
        if data then
            SafeDestroy(data.Highlight)
            SafeDestroy(data.Billboard)
            ESPObjects[object] = nil
        end
    end
end

PlayerESP = {Active = false, Data = {}, GlobalConns = {}}

function PE_DisconnectList(list)
    for _,connection in ipairs(list) do
        pcall(function() connection:Disconnect() end)
    end

    table.clear(list)
end

function PE_DestroyVisuals(data)
    SafeDestroy(data.Highlight)
    SafeDestroy(data.Billboard)
    data.Highlight = nil
    data.Billboard = nil
    data.NameLabel = nil
end

function PE_Detach(data)
    PE_DestroyVisuals(data)

    if data.CharConn then
        pcall(function() data.CharConn:Disconnect() end)
        data.CharConn = nil
    end

    data.Char = nil
end

function PE_Attach(player,data,character)
    PE_Detach(data)

    if not character or not PlayerESP.Active then return end

    data.Char = character

    local highlight = Instance.new("Highlight")
    highlight.Name = "LK_PLAYER_ESP"
    highlight.Adornee = character
    highlight.FillColor = Purple
    highlight.OutlineColor = Purple
    highlight.FillTransparency = 0.6
    highlight.OutlineTransparency = 0
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Parent = Gui
    data.Highlight = highlight

    data.CharConn = character.AncestryChanged:Connect(function(_,parent)
        if not parent and data.Char == character then
            PE_Detach(data)
        end
    end)

    task.spawn(function()
        local head = character:WaitForChild("Head",10)

        if not head or data.Char ~= character
        or not PlayerESP.Active or data.Billboard then
            return
        end

        local billboard = Instance.new("BillboardGui")
        billboard.Name = "LK_PLAYER_LABEL"
        billboard.Adornee = head
        billboard.Size = UDim2.fromOffset(150,34)
        billboard.StudsOffset = Vector3.new(0,2.6,0)
        billboard.AlwaysOnTop = true
        billboard.Parent = Gui

        local display = Instance.new("TextLabel")
        display.Size = UDim2.new(1,0,0.55,0)
        display.BackgroundTransparency = 1
        display.Text = player.DisplayName
        display.TextColor3 = White
        display.TextStrokeTransparency = 0
        display.TextSize = 13
        display.Font = Enum.Font.GothamBold
        display.Parent = billboard

        local username = Instance.new("TextLabel")
        username.Position = UDim2.fromScale(0,0.55)
        username.Size = UDim2.new(1,0,0.45,0)
        username.BackgroundTransparency = 1
        username.Text = "@"..player.Name
        username.TextColor3 = Purple
        username.TextStrokeTransparency = 0
        username.TextSize = 11
        username.Font = Enum.Font.GothamSemibold
        username.Parent = billboard

        data.Billboard = billboard
        data.NameLabel = display
    end)
end

function PE_Track(player)
    if player == Player or PlayerESP.Data[player] then return end

    local data = {Conns = {}}
    PlayerESP.Data[player] = data

    data.Conns[#data.Conns + 1] = player.CharacterAdded:Connect(function(character)
        PE_Attach(player,data,character)
    end)

    data.Conns[#data.Conns + 1] = player.CharacterRemoving:Connect(function()
        PE_Detach(data)
    end)

    data.Conns[#data.Conns + 1] = player:GetPropertyChangedSignal("DisplayName"):Connect(function()
        if data.NameLabel then
            data.NameLabel.Text = player.DisplayName
        end
    end)

    if player.Character then
        PE_Attach(player,data,player.Character)
    end
end

function PE_Untrack(player)
    local data = PlayerESP.Data[player]
    if not data then return end

    PE_Detach(data)
    PE_DisconnectList(data.Conns)
    PlayerESP.Data[player] = nil
end

function PE_Disable()
    PlayerESP.Active = false

    PE_DisconnectList(PlayerESP.GlobalConns)

    for player in pairs(PlayerESP.Data) do
        PE_Untrack(player)
    end
end

function PE_Enable()
    if PlayerESP.Active then return end
    PlayerESP.Active = true

    PlayerESP.GlobalConns[#PlayerESP.GlobalConns + 1] =
        Players.PlayerAdded:Connect(function(player)
            PE_Track(player)
        end)

    PlayerESP.GlobalConns[#PlayerESP.GlobalConns + 1] =
        Players.PlayerRemoving:Connect(function(player)
            PE_Untrack(player)
        end)

    for _,player in ipairs(Players:GetPlayers()) do
        PE_Track(player)
    end
end

function PE_Rebuild()
    if not PlayerESP.Active then return end

    for player,data in pairs(PlayerESP.Data) do
        PE_Attach(player,data,player.Character)
    end
end

CleanupHooks[#CleanupHooks + 1] = PE_Disable

BatteryESP = {Active = false, Items = {}, Token = nil}

function IsInsideCharacter(object)
    local current = object.Parent

    for _ = 1,8 do
        if not current or current == Workspace then return false end

        if current:IsA("Model") and current:FindFirstChildOfClass("Humanoid") then
            return true
        end

        current = current.Parent
    end

    return false
end

function HasCollectPrompt(object)
    local function promptOk(prompt)
        local action = (prompt.ActionText or ""):lower()
        local pname = Norm(prompt.Name)

        if HasAny(action,{"unlock","hide","open","destranc","esconder"}) then
            return false
        end

        if pname:find("hide",1,true) or pname:find("unlock",1,true) then
            return false
        end

        return true
    end

    if object:IsA("ProximityPrompt") then return promptOk(object) end

    local count = 0
    for _,descendant in ipairs(object:GetDescendants()) do
        count = count + 1
        if count > 150 then break end

        if descendant:IsA("ProximityPrompt") and promptOk(descendant) then
            return true
        end
    end

    return false
end

function ClassifyBattery(object)
    if not object.Parent or not object:IsDescendantOf(Workspace) then
        return false
    end

    if not (object:IsA("Model") or object:IsA("Tool") or object:IsA("BasePart")) then
        return false
    end

    if IsInsideCharacter(object) then return false end

    
    local ancestor = object.Parent
    for _ = 1,3 do
        if not ancestor or ancestor == Workspace then break end

        if (ancestor:IsA("Model") or ancestor:IsA("Tool"))
        and IsBatteryName(ancestor.Name) then
            return false
        end

        ancestor = ancestor.Parent
    end

    if not GetPart(object) then return false end

    
    if Norm(object.Name):find("^livebreakerpolepickup") then
        return true
    end

    
    if object:IsA("Tool") then return true end

    if object:IsA("BasePart") then
        local prompt = object:FindFirstChildOfClass("ProximityPrompt")
        return prompt ~= nil and HasCollectPrompt(prompt)
    end

    return HasCollectPrompt(object)
end

function BE_Remove(object)
    local data = BatteryESP.Items[object]
    if not data then return end

    SafeDestroy(data.Highlight)
    SafeDestroy(data.Billboard)
    BatteryESP.Items[object] = nil
end

function BE_Add(object)
    if BatteryESP.Items[object] then return end

    local color = Color3.fromRGB(0,255,200)

    local highlight = Instance.new("Highlight")
    highlight.Name = "LK_BATTERY_ESP"
    highlight.Adornee = object
    highlight.FillColor = color
    highlight.OutlineColor = color
    highlight.FillTransparency = 0.7
    highlight.OutlineTransparency = 0
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Parent = Gui

    local billboard
    local part = GetPart(object)

    if part then
        billboard = Instance.new("BillboardGui")
        billboard.Name = "LK_BATTERY_LABEL"
        billboard.Adornee = part
        billboard.Size = UDim2.fromOffset(110,24)
        billboard.StudsOffset = Vector3.new(0,2.5,0)
        billboard.AlwaysOnTop = true
        billboard.Parent = Gui

        local text = Instance.new("TextLabel")
        text.Size = UDim2.fromScale(1,1)
        text.BackgroundTransparency = 1
        text.Text = "BATTERY"
        text.TextColor3 = color
        text.TextStrokeTransparency = 0
        text.TextSize = 12
        text.Font = Enum.Font.GothamBold
        text.Parent = billboard
    end

    BatteryESP.Items[object] = {Highlight = highlight,Billboard = billboard}
end

function BE_Refresh()
    local found = {}

    -- Re-index current world objects on each refresh; this catches batteries
    -- spawned later, nested pickups, and objects missed during initial loading.
    for _,object in ipairs(Workspace:GetDescendants()) do
        if IsBatteryName(object.Name)
        and (object:IsA("Model") or object:IsA("Tool") or object:IsA("BasePart")) then
            Buckets.battery[object] = true
        end
    end

    for object in pairs(Buckets.battery) do
        if not object or not object:IsDescendantOf(Workspace) then
            Buckets.battery[object] = nil
            BE_Remove(object)
        else
            found[object] = true
            if ClassifyBattery(object) then
                BE_Add(object)
            else
                BE_Remove(object)
            end
        end
    end

    for object in pairs(BatteryESP.Items) do
        if not object or not object.Parent or not found[object] then
            BE_Remove(object)
        end
    end
end

function BE_ClearVisuals()
    for object in pairs(BatteryESP.Items) do
        BE_Remove(object)
    end
end

function BE_Disable()
    BatteryESP.Active = false
    BatteryESP.Token = nil
    BE_ClearVisuals()
end

function BE_Enable()
    if BatteryESP.Active then return end

    BatteryESP.Active = true

    local token = {}
    BatteryESP.Token = token

    task.spawn(function()
        while Running and BatteryESP.Token == token do
            local ok,err = pcall(BE_Refresh)

            if not ok then
                warn("LK BATTERY ESP ERROR:",err)
            end

            task.wait(1)
        end
    end)
end

CleanupHooks[#CleanupHooks + 1] = BE_Disable

EntitySkinObjects = {}
BuildEntitySkinMap = nil
function SetEntityOriginalVisible(model, visible, record)
    for _,item in ipairs(model:GetDescendants()) do
        if item:IsA("BasePart") then
            if visible then
                local old = record and record.OriginalTransparency and record.OriginalTransparency[item]
                item.LocalTransparencyModifier = old or 0
            else
                if record then
                    record.OriginalTransparency = record.OriginalTransparency or {}
                    if record.OriginalTransparency[item] == nil then
                        record.OriginalTransparency[item] = item.LocalTransparencyModifier
                    end
                end
                item.LocalTransparencyModifier = 1
            end
        elseif item:IsA("Decal") or item:IsA("Texture") then
            if visible then
                local old = record and record.OriginalDecalTransparency and record.OriginalDecalTransparency[item]
                item.Transparency = old or 0
            else
                if record then
                    record.OriginalDecalTransparency = record.OriginalDecalTransparency or {}
                    if record.OriginalDecalTransparency[item] == nil then
                        record.OriginalDecalTransparency[item] = item.Transparency
                    end
                end
                item.Transparency = 1
            end
        end
    end
end

function RemoveEntitySkin(model)
    local record = EntitySkinObjects[model]
    if not record then return end
    SetEntityOriginalVisible(model, true, record)
    SafeDestroy(record.Avatar)
    EntitySkinObjects[model] = nil
end

function ApplyEntitySkin(model)
    if not Settings.EntitySkin or not model or not model:IsA("Model")
    or not model.Parent or EntitySkinObjects[model] then return end

    local character = Player.Character
    if not character then return end

    local oldArchivable = character.Archivable
    local clone
    local ok = pcall(function()
        character.Archivable = true
        clone = character:Clone()
        character.Archivable = oldArchivable
    end)
    character.Archivable = oldArchivable
    if not ok or not clone then return end

    clone.Name = "LK_EntityPlayerSkin"

    
    
    for _,item in ipairs(clone:GetDescendants()) do
        if item:IsA("Tool") then
            item:Destroy()
        elseif item:IsA("Script") or item:IsA("LocalScript") then
            item:Destroy()
        elseif item:IsA("BasePart") then
            
            
            item.Anchored = true
            item.CanCollide = false
            item.CanTouch = false
            item.CanQuery = false
            item.Massless = true
        elseif item:IsA("Humanoid") then
            item.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            item.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
            item.NameDisplayDistance = 0
        end
    end

    local avatarParts = {}
    for _,part in ipairs(clone:GetDescendants()) do
        if part:IsA("BasePart") then
            avatarParts[part.Name:lower()] = part
        end
    end

    local record = {
        Avatar = clone,
        AvatarParts = avatarParts,
        OriginalTransparency = {},
        OriginalDecalTransparency = {}
    }
    EntitySkinObjects[model] = record

    pcall(function()
        clone:PivotTo(model:GetPivot())
        clone.Parent = Workspace
    end)
    record.PartMap = BuildEntitySkinMap(model, clone)
    record.AccessoryMap = BuildEntityAccessoryMap(clone, record.PartMap)
    SetEntityOriginalVisible(model, false, record)
end

function NormalizeEntityPartName(name)
    return tostring(name or ""):lower():gsub("[^%w]", "")
end

EntityPartAliases = {
    head = {"head", "skull", "face"},
    uppertorso = {"uppertorso", "torso", "body", "chest", "mainbody"},
    lowertorso = {"lowertorso", "torso", "body", "abdomen", "mainbody"},
    leftupperarm = {"leftupperarm", "leftarm", "armleft", "leftarm1", "arml"},
    leftlowerarm = {"leftlowerarm", "leftforearm", "leftarm", "armleft", "leftarm2"},
    lefthand = {"lefthand", "leftarm", "handleft", "leftclaw"},
    rightupperarm = {"rightupperarm", "rightarm", "armright", "rightarm1", "armr"},
    rightlowerarm = {"rightlowerarm", "rightforearm", "rightarm", "armright", "rightarm2"},
    righthand = {"righthand", "rightarm", "handright", "rightclaw"},
    leftupperleg = {"leftupperleg", "leftleg", "legleft", "leftleg1", "legl"},
    leftlowerleg = {"leftlowerleg", "leftleg", "legleft", "leftleg2"},
    leftfoot = {"leftfoot", "leftleg", "footleft"},
    rightupperleg = {"rightupperleg", "rightleg", "legright", "rightleg1", "legr"},
    rightlowerleg = {"rightlowerleg", "rightleg", "legright", "rightleg2"},
    rightfoot = {"rightfoot", "rightleg", "footright"}
}

BuildEntitySkinMap = function(model, avatar)
    local sourceParts, sourceList = {}, {}
    for _,part in ipairs(model:GetDescendants()) do
        if part:IsA("BasePart") then
            local key = NormalizeEntityPartName(part.Name)
            sourceParts[key] = sourceParts[key] or part
            if part.Name ~= "HumanoidRootPart" then
                sourceList[#sourceList + 1] = part
            end
        end
    end

    local map, used = {}, {}
    local _, avatarSize = avatar:GetBoundingBox()
    local _, entitySize = model:GetBoundingBox()
    local avatarPivot, entityPivot = avatar:GetPivot(), model:GetPivot()

    for _,avatarPart in ipairs(avatar:GetDescendants()) do
        if avatarPart:IsA("BasePart") and avatarPart.Name ~= "HumanoidRootPart" then
            local key = NormalizeEntityPartName(avatarPart.Name)
            local source = sourceParts[key]
            if not source then
                for _,alias in ipairs(EntityPartAliases[key] or {}) do
                    source = sourceParts[NormalizeEntityPartName(alias)]
                    if source then break end
                end
            end

            
            
            if not source and #sourceList > 0 then
                local rel = avatarPivot:PointToObjectSpace(avatarPart.Position)
                local target = Vector3.new(
                    rel.X / math.max(avatarSize.X, 0.01),
                    rel.Y / math.max(avatarSize.Y, 0.01),
                    rel.Z / math.max(avatarSize.Z, 0.01)
                )
                local bestScore = math.huge
                for _,candidate in ipairs(sourceList) do
                    if not used[candidate] then
                        local pos = entityPivot:PointToObjectSpace(candidate.Position)
                        local normalized = Vector3.new(
                            pos.X / math.max(entitySize.X, 0.01),
                            pos.Y / math.max(entitySize.Y, 0.01),
                            pos.Z / math.max(entitySize.Z, 0.01)
                        )
                        local score = (target - normalized).Magnitude
                        
                        local volume = candidate.Size.X * candidate.Size.Y * candidate.Size.Z
                        if volume < 0.002 then score = score + 2 end
                        if score < bestScore then
                            bestScore, source = score, candidate
                        end
                    end
                end
            end
            if source then
                map[avatarPart] = source
                used[source] = true
            end
        end
    end
    return map
end

function BuildEntityAccessoryMap(avatar, partMap)
    local attachmentOwners = {}
    for avatarPart, sourcePart in pairs(partMap or {}) do
        if avatarPart and avatarPart.Parent and sourcePart and sourcePart.Parent then
            for _,obj in ipairs(avatarPart:GetChildren()) do
                if obj:IsA("Attachment") then
                    attachmentOwners[obj.Name] = sourcePart
                end
            end
        end
    end

    local accessoryMap = {}
    for _,obj in ipairs(avatar:GetDescendants()) do
        if obj:IsA("Accessory") then
            local handle = obj:FindFirstChild("Handle")
            if handle and handle:IsA("BasePart") then
                for _,handleAttachment in ipairs(handle:GetChildren()) do
                    if handleAttachment:IsA("Attachment") then
                        local targetPart = attachmentOwners[handleAttachment.Name]
                        if targetPart then
                            accessoryMap[#accessoryMap + 1] = {
                                Handle = handle,
                                HandleAttachment = handleAttachment,
                                TargetPart = targetPart
                            }
                            break
                        end
                    end
                end
            end
        end
    end
    return accessoryMap
end

function SyncEntityAccessories(record)
    for _,entry in ipairs(record.AccessoryMap or {}) do
        local handle = entry.Handle
        local attachment = entry.HandleAttachment
        local targetPart = entry.TargetPart
        if handle and handle.Parent and attachment and attachment.Parent
        and targetPart and targetPart.Parent then
            
            
            pcall(function()
                handle.CFrame = targetPart.CFrame
                    * attachment.CFrame:Inverse()
            end)
        end
    end
end

function SyncEntitySkinPose(model, record)
    if not record or not record.Avatar or not record.Avatar.Parent then return end
    local avatar = record.Avatar
    pcall(function() avatar:PivotTo(model:GetPivot()) end)

    
    for avatarPart, sourcePart in pairs(record.PartMap or {}) do
        if avatarPart and avatarPart.Parent and sourcePart and sourcePart.Parent then
            pcall(function()
                avatarPart.CFrame = sourcePart.CFrame
            end)
        end
    end

    
    SyncEntityAccessories(record)
end

function RefreshEntitySkins()
    if not Settings.EntitySkin then
        for model in pairs(EntitySkinObjects) do
            RemoveEntitySkin(model)
        end
        return
    end

    for model in pairs(Buckets.entity) do
        if model and model.Parent and model:IsDescendantOf(Workspace) then
            if not EntitySkinObjects[model] then
                ApplyEntitySkin(model)
            else
                local record = EntitySkinObjects[model]
                SyncEntitySkinPose(model, record)
            end
        else
            RemoveEntitySkin(model)
        end
    end

    for model in pairs(EntitySkinObjects) do
        if not model or not model.Parent or not model:IsDescendantOf(Workspace) then
            RemoveEntitySkin(model)
        end
    end
end

CleanupHooks[#CleanupHooks + 1] = function()
    for model in pairs(EntitySkinObjects) do
        RemoveEntitySkin(model)
    end
end

Track(RunService.Heartbeat:Connect(function()
    if Settings.EntitySkin then
        RefreshEntitySkins()
    end
end))

